import {choose,chooseExcept,percent,loadState,spendDraw,rewardShare,STORAGE_KEY} from './engine.4f1a4a529001.js';
function creditArtist(s){const a=s.artist||s.source;const labels={"저작자 미상":"Urheber unbekannt","Unknown author":"Urheber unbekannt","\\nUnknown artistUnknown artist":"Urheber unbekannt","원본 출처 표기 참고":"Urheberangabe in der Originalquelle beachten","Generated with OpenAI image generation":"Mit OpenAI image generation erstellt"};return labels[a]||(a.trim()==="Unknown artistUnknown artist"?labels["Unknown author"]:a);}
const $=id=>document.getElementById(id);let categories=[],sources=[],current=null,currentRound=0,busy=false,storage,state;

function track(action,id){if(!['draw','redraw','share_prepare'].includes(action)||!categories.some(c=>c.id===id))return;try{window.gtag?.('event','rebirth_biology_action',{game_id:'rebirth_biology',action,result_id:id});}catch{}}
try{storage=window.localStorage;}catch{}state=loadState(storage);
const groupNames={Bacteria:'Bakterien',Archaea:'Archaeen',Fungi:'Pilze',Protists:'Protisten',Animals:'Tiere',Plants:'Pflanzen'};
let toastTimer;function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3400);}
function refresh(){if(storage)state=loadState(storage);}
function persist(){try{storage?.setItem(STORAGE_KEY,JSON.stringify(state));}catch{storage=null;toast('Das Speichern im Browser ist blockiert. Die Anzahl bleibt nur in diesem Tab erhalten.');}}
function updateCredits(){const previous=categories.find(c=>c.id===state.lastId);$('draw').disabled=!categories.length||busy;$('draw').textContent=previous?'Meinen Lebensausweis ansehen ↗':'Mein nächstes Leben ziehen ↗';$('home-credit').textContent=state.started?`Noch ${state.remaining} Versuche · Teilen gibt +2`:'Erste Ziehung kostenlos · 1 weiterer Versuch';$('retry').disabled=state.remaining===0||busy;$('retry-exclude').disabled=state.remaining===0||busy||!current;$('retry').textContent=state.remaining?`Erneut ziehen · noch ${state.remaining} ↻`:'Keine Versuche mehr';$('credit-status').textContent=`Noch ${state.remaining} Versuche · Teilen gibt +2`;$('share-rule').textContent=state.rewardedRound===currentRound?"Teilbonus für diesen Ausweis bereits erhalten":"Ein Bonus je Ausweis · Teilanfrage oder kopierter Link";}
function screen(view){for(const id of ['home','loading','result'])$(id).hidden=id!==view;}
function address(c){const a=["Irgendwo in der Tiefsee","Irgendwo im blauen Ozean","Irgendwo tief unter der Erde","Irgendwo im Erdboden","Irgendwo im Grünen auf der Erde","Irgendwo hier auf der Erde","Irgendwo auf der belebten Erde"];if(['bio-04','bio-08'].includes(c.id))return a[0];if(['bio-01','bio-05'].includes(c.id))return a[2];if(['bio-03','bio-07','bio-16'].includes(c.id))return a[3];if(c.group==='Plants')return a[4];if(c.id==='bio-20')return a[5];if(c.id.startsWith('bio-24-')||['bio-02','bio-06','bio-10','bio-13-1','bio-13-2','bio-14','bio-15','bio-17','bio-18','bio-23'].includes(c.id))return a[1];return a[6];}
function motto(c){const m=["Trotz geringer Chancen wieder ein Mensch.","Diesmal ein ruhigeres Leben.","Ein neues Leben, das zum Sonnenlicht wächst.","Auch ein kleiner Körper birgt eine ganze Welt.","Das Leben geht auch im Verborgenen weiter.","Kleine Welten haben große Geschichten.","Ein neuer Körper. Ein neues Leben."];if(c.id==='bio-20')return m[0];if(c.id==='land-mammal-12')return m[1];if(c.group==='Plants')return m[2];if(['Bacteria','Archaea'].includes(c.group))return m[3];if(c.group==='Fungi')return m[4];if(c.group==='Protists')return m[5];return m[6];}
function shareURL(c){return new URL(`r/${c.id}/?card=1`,document.baseURI).href;}
function viewResult(c,{navigate=true,round=state.round}={}){current=c;currentRound=round;$('result-name').textContent=c.name;$('result-line').textContent=motto(c);$('card-name').textContent=c.name;$('card-name').classList.toggle('long-name',c.name.length>9);$('card-latin').textContent=c.scientificName||c.group.toUpperCase();$('card-group').textContent=c.rank==='species'?`${groupNames[c.group]} · Ergebnis auf Artebene`:`${groupNames[c.group]} · Ergebnis auf Gruppenebene`;$('card-address').textContent=address(c);$('card-probability').textContent=percent(c.probability)+'%';$('result-image').src=c.image;$('result-image').alt=c.name+(c.imageRole==='species'?'':' Repräsentatives Gruppenbild');const i=categories.indexOf(c)+1;$('specimen-id').textContent=`EXEMPLAR ${String(i).padStart(3,'0')}`;$('card-number').textContent=`BIO · 2026 · ${String(i).padStart(3,'0')}`;
const s=sources.find(s=>s.categoryId===c.id);$('image-caption').textContent=s?.imageRole==='conceptual-illustration'?'KI-generierte Konzeptillustration · Kein echtes Foto einer bestimmten Art.':c.imageRole==='species'?'Bild der Art und fiktiver biologischer Spielausweis':`Repräsentatives Gruppenbild${s?.depictedTaxon?' · '+s.depictedTaxon:''} · keine Wahrscheinlichkeit für die einzelne Art`;
$('image-credit').replaceChildren();if(s){const text=document.createElement('span');text.textContent=`Bild: ${creditArtist(s)} · ${s.license} · zugeschnitten und konvertiert `;$('image-credit').append(text);if(s.sourceUrl){const a=document.createElement('a');a.href=s.sourceUrl;a.target='_blank';a.rel='noopener';a.textContent='Originalquelle ↗';$('image-credit').append(a);}if(s.licenseUrl){const a=document.createElement('a');a.href=s.licenseUrl;a.target='_blank';a.rel='noopener';a.textContent=' · Lizenz ↗';$('image-credit').append(a);}}
updateCredits();screen('result');document.title=`Mein nächstes Leben: ${c.name} · Lebensausweis`;if(navigate)history.pushState({view:'result',id:c.id,round},'',shareURL(c));window.scrollTo({top:0,behavior:'smooth'});}
async function draw(retry=false,excludeCurrent=false){if(busy||!categories.length)return;refresh();if(!retry&&state.started&&state.lastId){const previous=categories.find(c=>c.id===state.lastId);if(previous){viewResult(previous);return;}}if(!spendDraw(state)){toast('Wenn du deinen Ausweis teilst, erhältst du 2 weitere Versuche.');return;}const excludedId=excludeCurrent?current?.id:null;const c=excludedId?chooseExcept(categories,excludedId):choose(categories);state.lastId=c.id;persist();track(retry?'redraw':'draw',c.id);busy=true;updateCredits();screen('loading');window.scrollTo({top:0,behavior:'smooth'});let i=0;const timer=setInterval(()=>{$('loading-name').textContent=categories[(i++*7)%categories.length].name+' — beginnt ein neues Leben?';},140);await new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?120:1900));clearInterval(timer);busy=false;viewResult(c);}
$('draw').onclick=()=>draw();$('retry').onclick=()=>draw(true);$('retry-exclude').onclick=()=>draw(true,true);$('reload').onclick=()=>location.reload();
function home({navigate=true}={}){current=null;screen('home');refresh();updateCredits();document.title='Als welches Lebewesen wirst du wiedergeboren? · Lebensausweis';if(navigate)history.pushState({view:'home'},'',new URL('./',document.baseURI));window.scrollTo({top:0,behavior:'smooth'});}
$('back-home').onclick=()=>home();document.querySelectorAll('.brand').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();home();}));
function grantShare(round,id){refresh();if(state.round!==round||state.lastId!==id){toast('Hole den Bonus über deinen zuletzt ausgestellten Ausweis.');return;}if(rewardShare(state)){persist();track('share_prepare',id);updateCredits();toast('Teilbonus: 2 weitere Versuche wurden hinzugefügt.');}else toast('Der Teilbonus für diesen Ausweis wurde bereits erhalten.');}
async function copy(){if(!current)return;const round=currentRound,id=current.id,url=shareURL(current);let copied=false;try{await navigator.clipboard.writeText(url);copied=true;}catch{const input=document.createElement('textarea');input.value=url;input.style.position='fixed';input.style.top='0';document.body.append(input);input.select();copied=document.execCommand('copy');input.remove();}if(copied)grantShare(round,id);else toast('Kopieren ist blockiert. Kopiere den Link aus der Adresszeile.');}
$('copy').onclick=copy;$('share').onclick=async()=>{if(!current)return;const round=currentRound,id=current.id;const data={title:`Mein nächstes Leben: ${current.name}`,text:`Mein nächstes Leben ist ${current.name}! Chance: ${percent(current.probability)} %. Was wirst du?`,url:shareURL(current)};if(navigator.share){try{await navigator.share(data);grantShare(round,id);}catch(e){if(e.name!=='AbortError')toast('Das Teilen-Fenster konnte nicht geöffnet werden. Nutze unten „Link kopieren“.');}}else toast('Dieser Browser kann das Teilen-Fenster nicht öffnen. Nutze unten „Link kopieren“.');};
function social(network){if(!current)return;const url=encodeURIComponent(shareURL(current)),text=encodeURIComponent(`Mein nächstes Leben: ${current.name}, Chance ${percent(current.probability)} %. Was wirst du?`);const target=network==='x'?`https://x.com/intent/tweet?text=${text}&url=${url}`:`https://www.facebook.com/sharer/sharer.php?u=${url}`;const popup=window.open(target,'_blank','width=640,height=650');if(popup){popup.opener=null;grantShare(currentRound,current.id);}else toast('Das Teilen-Fenster ist blockiert. Nutze „Link kopieren“.');}
$('share-x').onclick=()=>social('x');$('share-facebook').onclick=()=>social('facebook');$('save').onclick=()=>{if(!current)return;const a=document.createElement('a');a.href=new URL(`og/${current.id}.jpg`,document.baseURI);a.download=`next-life-${current.id}.jpg`;document.body.append(a);a.click();a.remove();toast('Speichern des Ausweises als JPG gestartet.');};
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>$(b.dataset.open).showModal());document.querySelectorAll('dialog').forEach(d=>{d.querySelectorAll('.close,.dialog-close').forEach(b=>b.onclick=()=>d.close());d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});});
addEventListener('popstate',e=>{const c=e.state?.view==='result'?categories.find(c=>c.id===e.state.id):null;if(c)viewResult(c,{navigate:false,round:e.state.round});else home({navigate:false});});addEventListener('storage',e=>{if(e.key===STORAGE_KEY){refresh();updateCredits();}});
async function init(){screen('home');document.title='Als welches Lebewesen wirst du wiedergeboren? · Lebensausweis';history.replaceState({view:'home'},'',location.href);try{const responses=await Promise.all(['categories.json','image-sources.json'].map(p=>fetch(new URL(p,document.baseURI))));if(responses.some(r=>!r.ok))throw Error('Daten nicht verfügbar');[categories,sources]=await Promise.all(responses.map(r=>r.json()));if(categories.length!==72)throw Error('Ungültige Anzahl an Ergebnissen');const human=categories.find(c=>c.id==='bio-20');$('human-chance').textContent='etwa '+percent(human.probability)+'%';for(const id of ['land-mammal-12','bio-13-1','bio-24-5','bio-09','land-mammal-22','bio-26']){const c=categories.find(c=>c.id===id),item=document.createElement('article');item.className='sample';const img=document.createElement('img');img.src=c.image;img.alt=c.name;img.width=300;img.height=300;img.loading='lazy';const box=document.createElement('div'),h=document.createElement('h3'),small=document.createElement('small');h.textContent=c.name;small.textContent=groupNames[c.group]+' · NÄCHSTES LEBEN';box.append(h,small);item.append(img,box);$('sample-strip').append(item);}updateCredits();}catch{$('draw').disabled=true;$('draw').textContent='Informationen konnten nicht geladen werden';$('load-error').hidden=false;}}
init();
